export type SerializedNode = {type: string; $slots?: Record<string, SerializedNode>};
export type SerializedPartialNode = {
  type?: string;
  $slots?: Record<string, SerializedPartialNode | SerializedNode>;
};

export declare function take(values: Record<string, unknown>): void;
export declare function takeNumbers(values: Record<string, number>): void;
export declare function takeIndexed(values: {[key: string]: unknown}): void;

export declare class BaseNode {
  static importJSON(json: Record<string, unknown>): BaseNode;
  exportJSON(): SerializedPartialNode;
}

export type KlassConstructor<Cls extends new (...args: any[]) => any> =
  (new (...args: any[]) => InstanceType<Cls>) & {[K in keyof Cls]: Cls[K]};
export declare function register(klass: KlassConstructor<typeof BaseNode>): void;

// The default must satisfy the bound: `never` values are assignable to `RegExpMatchArray`.
export interface Selector<C extends Record<string, RegExpMatchArray> = Record<string, never>> {
  captures: C;
}

import type {Box, Cat, Dict, DictD, Fn, Handler, K, Spread, Typed} from '../../flow_alias';

// TypeScript applies a Flow alias: the types its body builds are TypeScript's.
export declare function takeDict(values: Dict<unknown>): void;
// A reference without type arguments applies the alias to its defaults.
export declare function takeDictD(values: DictD): void;
export declare function takeSpread(values: Spread<Typed>): void;
export declare function mkFn<T>(x: T): Fn<T>;
export type FnT<T> = (x: T) => void;
export declare function mkFnT<T>(x: T): FnT<T>;
export declare const ka: K<'a'>;
export declare function takeK(k: K<string>): void;
// Flow classes and interfaces keep their own semantics.
export declare function takeCatBox(box: Box<Cat>): void;
export declare function takeHandler(handler: Handler<string | number>): void;
